+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.regex.Pattern;
+
+/**
+ * A filter understood by {@link CustomerRepository}.
+ *
+ * <p>A customer matches when every whitespace-separated term of {@code name}
+ * appears in its first or last name (ignoring case and accents), and its status
+ * is one of {@code statuses}. An empty name or an empty status set matches
+ * everyone.
+ *
+ * @param name     free text typed by the user; never {@code null}
+ * @param statuses statuses to keep; empty means all; never {@code null}
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** The filter that matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("(?U)\\s+");
+    private static final Pattern MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                : Set.copyOf(EnumSet.copyOf(statuses));
+    }
+
+    /** The normalized search terms of {@link #name()}; empty when there are none. */
+    public List<String> nameTerms() {
+        String normalized = normalize(name).strip();
+        if (normalized.isEmpty()) {
+            return List.of();
+        }
+        return Arrays.asList(WHITESPACE.split(normalized));
+    }
+
+    public boolean isEmpty() {
+        return nameTerms().isEmpty() && statuses.isEmpty();
+    }
+
+    /** Lower-cases text and strips accents, so that {@code Mäkinen} becomes {@code makinen}. */
+    public static String normalize(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFKD);
+        return MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
